{"path": "zipper.py", "content": "class Zipper:
    """Zipper over a binary tree of dicts: {"value": v, "left": t|None, "right": t|None}.

    The focus subtree is stored alongside a list of breadcrumbs; each crumb is
    (direction, parent_value, other_subtree) describing how to rebuild the parent.
    """

    def __init__(self, focus, crumbs):
        self._focus = focus
        self._crumbs = crumbs

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, [])

    def value(self):
        return self._focus["value"]

    def set_value(self, value):
        return Zipper(
            {"value": value, "left": self._focus["left"], "right": self._focus["right"]},
            self._crumbs,
        )

    def left(self):
        child = self._focus["left"]
        if child is None:
            return None
        crumb = ("left", self._focus["value"], self._focus["right"])
        return Zipper(child, self._crumbs + [crumb])

    def set_left(self, tree):
        return Zipper(
            {"value": self._focus["value"], "left": tree, "right": self._focus["right"]},
            self._crumbs,
        )

    def right(self):
        child = self._focus["right"]
        if child is None:
            return None
        crumb = ("right", self._focus["value"], self._focus["left"])
        return Zipper(child, self._crumbs + [crumb])

    def set_right(self, tree):
        return Zipper(
            {"value": self._focus["value"], "left": self._focus["left"], "right": tree},
            self._crumbs,
        )

    def up(self):
        if not self._crumbs:
            return None
        direction, value, other = self._crumbs[-1]
        if direction == "left":
            parent = {"value": value, "left": self._focus, "right": other}
        else:
            parent = {"value": value, "left": other, "right": self._focus}
        return Zipper(parent, self._crumbs[:-1])

    def to_tree(self):
        zipper = self
        while zipper._crumbs:
            zipper = zipper.up()
        return zipper._focus

    def __eq__(self, other):
        if not isinstance(other, Zipper):
            return NotImplemented
        return self._focus == other._focus and self._crumbs == other._crumbs
